import{_ as o,c as t,o as r,ag as e}from"./chunks/framework.DPDPlp3K.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"shopify/storefronts/性能问题排查(性能优化).md","filePath":"shopify/storefronts/性能问题排查(性能优化).md"}'),p={name:"shopify/storefronts/性能问题排查(性能优化).md"};function h(i,a,s,n,l,d){return r(),t("div",null,a[0]||(a[0]=[e('<h2 id="标题备选" tabindex="-1">标题备选 <a class="header-anchor" href="#标题备选" aria-label="Permalink to &quot;标题备选&quot;">​</a></h2><ol><li>Shopify 开发实战：Shopify 主题性能问题排查 一篇讲清楚</li><li>手把手梳理 Shopify：Shopify 主题性能问题排查 的关键用法和避坑点</li><li>做 Shopify 项目别只会改主题，这篇带你搞懂 Shopify 主题性能问题排查</li></ol><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>这篇文章适合 Shopify 主题和应用开发者，围绕「Shopify 主题性能问题排查」梳理核心概念、配置路径和实战注意点，方便项目中快速对照。</p><h2 id="正文" tabindex="-1">正文 <a class="header-anchor" href="#正文" aria-label="Permalink to &quot;正文&quot;">​</a></h2><p>哈喽大家好👋 我是程序🦍kk。把复杂知识掰成大白话讲明白，是我一直以来的小追求✨；<strong>打好基础才能稳步进阶</strong>，是我始终秉持的学习理念～</p><blockquote><p>📢 我搭建了5000人程序猿专属学习交流群，群内会同步前端开发/全栈开发/Web3开发/远程工作等干货资源，关注我并回复 <strong>加群</strong> ，就能加入交流圈啦🚀</p></blockquote><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p><strong>Shopify 项目最容易卡住的地方，往往不是“会不会写代码”，而是主题、应用和后台配置之间的关系没理顺。</strong></p><p>很多同学做 Shopify 开发时，会同时碰到 Liquid、主题目录、Checkout、Metafields、应用后台、性能优化这些概念。单独看不难，放到真实项目里就容易散。</p><p>这篇围绕「Shopify 主题性能问题排查」把原始笔记整理成更适合阅读和复用的版本，适合做主题开发、应用开发或者接手 Shopify 项目时快速对照。</p><h2 id="shopify-实战整理" tabindex="-1">Shopify 实战整理 <a class="header-anchor" href="#shopify-实战整理" aria-label="Permalink to &quot;Shopify 实战整理&quot;">​</a></h2><p>下面进入 Shopify 相关内容整理。建议大家边看边对照自己的店铺、主题代码和应用后台，很多问题只有放到真实配置里才容易看清楚。</p><p>如果你正在做 Shopify 项目，可以重点留意主题代码、后台配置、应用能力和官方限制之间的边界，很多线上问题都出在这些交界处。</p><h2 id="性能问题排查案例" tabindex="-1">性能问题排查案例 <a class="header-anchor" href="#性能问题排查案例" aria-label="Permalink to &quot;性能问题排查案例&quot;">​</a></h2><h2 id="排查-add-to-cart-延迟的根源" tabindex="-1">排查 Add to Cart 延迟的根源 <a class="header-anchor" href="#排查-add-to-cart-延迟的根源" aria-label="Permalink to &quot;排查 Add to Cart 延迟的根源&quot;">​</a></h2><h3 id="_1-🔍-先定位延迟类型" tabindex="-1">1. 🔍 先定位延迟类型 <a class="header-anchor" href="#_1-🔍-先定位延迟类型" aria-label="Permalink to &quot;1. 🔍 先定位延迟类型&quot;">​</a></h3><p>打开浏览器开发者工具（F12）→ Network 标签，点击&quot;加入购物车&quot;按钮，观察：</p><p>请求发送到 /cart/add.js 的响应时间是多少？ 是请求本身慢（后端问题），还是请求很快但页面响应慢（前端/JS 问题）？</p><h3 id="_2-🛒-常见原因排查" tabindex="-1">2. 🛒 常见原因排查 <a class="header-anchor" href="#_2-🛒-常见原因排查" aria-label="Permalink to &quot;2. 🛒 常见原因排查&quot;">​</a></h3><p>前端/主题层面：</p><p>主题 JS 冲突：多个 App 注入了 cart 相关脚本，互相等待 Cart drawer 渲染慢：加入购物车后触发了复杂的 DOM 更新或动画 第三方 App 脚本阻塞：如推荐、评价、捆绑销售类 App 监听了 cart 事件 App 层面：</p><p>检查已安装的 App 是否有 cart hook / cart transform（如 Bundle、Upsell 类 App） 在 Shopify Admin → Settings → Custom data → Cart transforms 查看是否有激活的 cart transform 网络/服务器层面：</p><p>测试不同地区的响应时间（AU 用户访问 au.ecoflow.com 是否有 CDN 覆盖？） 检查 Shopify Status Page 是否有区域性故障</p><h3 id="_3-🧪-快速验证方法" tabindex="-1">3. 🧪 快速验证方法 <a class="header-anchor" href="#_3-🧪-快速验证方法" aria-label="Permalink to &quot;3. 🧪 快速验证方法&quot;">​</a></h3><p>禁用 App 脚本测试： 在主题编辑器中临时切换到 Shopify 默认主题（Dawn），测试同一产品的加入购物车速度，如果明显变快 → 问题在当前主题或 App 脚本。</p><p>逐一禁用 App： 在 App 管理页面逐一暂停可疑 App，每次测试 ATC 速度，定位具体是哪个 App 造成的。</p><h3 id="_4-📊-量化延迟" tabindex="-1">4. 📊 量化延迟 <a class="header-anchor" href="#_4-📊-量化延迟" aria-label="Permalink to &quot;4. 📊 量化延迟&quot;">​</a></h3><p>用 Chrome DevTools 的 Performance 录制，点击 ATC 按钮，查看：</p><p>Long Tasks（超过 50ms 的任务） 哪个脚本占用了主线程时间</p><hr><p>下面我给你一份 <strong>“网页性能优化指标 + DevTools Performance + Lighthouse + PageSpeed Insights”</strong> 的<strong>体系化介绍</strong>。 你可以把它当成 <strong>测试 / 前端 / 性能评估的速读指南</strong> ✅</p><hr><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>好啦，今天的分享就到这里！</p><p>💬 互动时间：</p><p>你现在做 Shopify 更常遇到的是主题开发、Checkout 定制、应用接入，还是性能优化？如果你在「Shopify 主题性能问题排查」上踩过坑，也可以把场景留言出来。</p><p>最后，感谢你看到这里👏</p><p>如果喜欢这篇内容，不妨顺手给小编安排一波👇 <strong>点赞</strong>👍｜<strong>转发</strong>📲｜<strong>推荐</strong>❤️｜<strong>评论</strong>📣</p><p>要是想第一时间蹲到新内容推送，记得给我点个<strong>星标</strong>⭐️</p><p>更多干货内容正在持续填坑中，咱们下期见👋</p><h2 id="标签建议" tabindex="-1">标签建议 <a class="header-anchor" href="#标签建议" aria-label="Permalink to &quot;标签建议&quot;">​</a></h2><p>Shopify、主题开发、独立站</p>',43)]))}const u=o(p,[["render",h]]);export{c as __pageData,u as default};
